  const context = (): HostContext => ({ sessionId: status.session.id ?? 'preview', recentConversation: history.slice(-12), currentScene: 'AVATAR', humanHostPresent: humanPresent, humanHostState: humanState });
  function showResult(reply: HostGenerationResult,avatarTrigger:HostTrigger='MANUAL',syncAvatar=true,speak=true) { if (!reply.ok) { setResult(null); setNotice(reply.message); setHostState(reply.code === 'AI_OFFLINE' || reply.code === 'MODEL_NOT_FOUND' || reply.code === 'AI_TIMEOUT' || reply.code === 'INVALID_AI_RESPONSE' ? 'ERROR' : 'READY'); return; } setResult(reply);if(syncAvatar)void window.desktop.avatarHostResponse(reply.response,avatarTrigger); setHistory(items => [...items, { role: 'host' as const, text: reply.response.speech, timestamp: new Date().toISOString() }].slice(-12)); setNotice(''); setHostState(speak?'THINKING':'READY');if(speak)void window.desktop.speak({text:reply.response.speech,language:voiceLanguage,voice:voiceId,cacheable:false}).then(r=>{if(!r.accepted){void window.desktop.avatarSpeechFailed();setNotice(r.error??'Voice request rejected');setHostState('READY')}}).catch(()=>{void window.desktop.avatarSpeechFailed();setHostState('READY')}); }
  async function generate(trigger: HostTrigger, text: string) { void audioEngine.unlock();setBusy(true); setHostState('THINKING'); setNotice(''); try { const request: HostRequest = { type: 'HOST_RESPONSE', trigger, context: context(), ...(text ? { instruction: text } : {}) }; showResult(await window.desktop.generateHost(request),trigger); } catch { setHostState('ERROR'); setNotice('AI ERROR'); } finally { setBusy(false); } }
  async function toggleLive() { void audioEngine.unlock();if (status.session.status === 'running') { setBusy(true); try { await window.desktop.stopSession(); setStatus(await window.desktop.getStatus());setAutonomyStatus(await window.desktop.getAutonomyStatus()); setHostState('STOPPED'); setNotice('Local host session stopped'); } finally { setBusy(false); } return; } setBusy(true); setHostState('STARTING'); setNotice(''); try { const session = await window.desktop.startSession(); setStatus(s => ({ ...s, session }));if(status.autonomyEnabled){setAutonomyStatus(await window.desktop.getAutonomyStatus());setHostState('READY');setNotice('Autonomous host started');return;} setHostState('THINKING'); const request: HostRequest = { type: 'HOST_RESPONSE', trigger: 'MANUAL', context: { ...context(), sessionId: session.id }, instruction: 'Sapa audience secara singkat. Jangan mengarang jumlah atau interaksi penonton.' }; showResult(await window.desktop.generateHost(request)); } catch { setHostState('ERROR'); setNotice('Could not start local host session'); } finally { setBusy(false); } }
  async function setAutonomy(enabled: boolean) { try { const saved = await window.desktop.setAutonomy(enabled); setStatus(s => ({ ...s, autonomyEnabled: saved.enabled }));setAutonomyStatus(await window.desktop.getAutonomyStatus()); setNotice(enabled ? (status.session.status==='running'?'Autonomy ON · hosting loop started':'Autonomy ON · starts with the next live session') : 'Autonomy OFF · manual requests only'); } catch { setNotice('Could not change autonomy'); } }
