  async function saveProduct(event: React.FormEvent) { event.preventDefault(); const name=productName.trim(); if(!name)return; setBusy(true); try { const saved=await window.desktop.saveProduct({id:`product-${crypto.randomUUID()}`,name,category:productCategory.trim(),price:productPrice?Number(productPrice):null,currency:productPrice?productCurrency:null,promoPrice:productDetails.promoPrice?Number(productDetails.promoPrice):null,description:productDetails.description.trim(),benefits:splitList(productDetails.benefits),specifications:splitList(productDetails.specifications),variants:splitList(productDetails.variants),stock:productStock?Number(productStock):null,images:splitList(productDetails.images),status:'ACTIVE',sellingPoints:splitList(productDetails.sellingPoints),targetAudience:splitList(productDetails.targetAudience),preferredTalkingPoints:splitList(productDetails.preferredTalkingPoints),forbiddenClaims:splitList(productDetails.forbiddenClaims),priority:50}); setProducts(items=>[...items.filter(p=>p.id!==saved.id),saved].sort((a,b)=>a.name.localeCompare(b.name))); setProductName('');setProductCategory('');setProductPrice('');setProductStock('');setProductDetails({description:'',promoPrice:'',benefits:'',specifications:'',variants:'',images:'',sellingPoints:'',targetAudience:'',preferredTalkingPoints:'',forbiddenClaims:''});setNotice('Product saved to the local catalog'); } catch { setNotice('Product data is invalid'); } finally { setBusy(false); } }
  async function selectProduct() { setBusy(true);setHostState('THINKING');setNotice('');try {const reply=await window.desktop.selectProduct({context:context(),conversation:history.slice(-6).map(x=>x.text).join(' ')});setSelection(reply.decision?`Selected: ${products.find(p=>p.id===reply.decision?.productId)?.name??reply.decision.productId}`:'No eligible product');showResult(reply.result,'PRODUCT_INTRO');}catch{setNotice('Could not select a catalog product');setHostState('ERROR');}finally{setBusy(false);} }
