  async function runAutomatedChecks(){if(automationBusy)return;setAutomationBusy(true);setNotice('Running automated checks: npm test, typecheck, build, and audit.');try{const result=await window.desktop.runPhase11AutomatedChecks();setValidation(result);setNotice(result.overall==='READY_FOR_NEXT_PHASE'?'Automated checks completed; required operator validation also appears satisfied.':'Automated checks finished. Review each recorded result and complete pending operator checks.')}catch{setNotice('Automated validation runner failed to start')}finally{setAutomationBusy(false)}}
