  async function runEmergencyValidation(){if(audioDiagnosticBusy)return;const track=musicTracks.find(t=>t.enabled&&t.durationMs&&t.category==='FULL_SONG')??musicTracks.find(t=>t.enabled&&t.durationMs);if(!track||!voiceStatus.indonesianVoiceAvailable||audioStatus.emergencyStopped){setNotice('Emergency test needs an enabled local music track, Indonesian voice, and a reset system.');return}setAudioDiagnosticBusy(true);try{void audioEngine.unlock();const outputs=await enumerateAudioOutputs();const device=outputs.find(d=>d.isDefault&&d.available)??outputs.find(d=>d.available);if(!device||!await window.desktop.setAudioDevice(device.id)){setNotice('Audio output is unavailable; emergency test was not started.');return}const source=await window.desktop.resolveAudioAsset('music',track.id);if(!source){setNotice('Local music asset could not be loaded; emergency test was not started.');return}const music=await startDiagnosticMusic('phase11-emergency-music',source,track.durationMs??5000);if(!music.started){setNotice('Music did not start; emergency test was not started.');return}const speech=await window.desktop.speak({text:'Ini pengujian penghentian darurat.',language:'id-ID',voice:voiceId,priority:'HIGH',cacheable:false});if(!speech.accepted){music.stop();setNotice('Indonesian voice did not start; emergency test was not started.');return}let overlap=false;const deadline=Date.now()+12000;while(Date.now()<deadline){const [voice,audio]=await Promise.all([window.desktop.getVoiceStatus(),window.desktop.getAudioState()]);if(voice.state==='PLAYING'&&audio.ducked&&music.stillPlaying()){overlap=true;break}if(voice.state==='FAILED')break;await new Promise(resolve=>setTimeout(resolve,50))}if(!overlap){await window.desktop.stopAllAudio();music.stop();audioEngine.stop();setNotice('Could not verify simultaneous speech, music, and ducking; emergency test remains NOT_TESTED.');return}const ok=await window.desktop.emergencyAudioStop();audioEngine.emergencyStop();music.stop();const [voice,audio,runtime,avatar,broadcast]=await Promise.all([window.desktop.getVoiceStatus(),window.desktop.getAudioState(),window.desktop.getLiveRuntime(),window.desktop.getAvatarState(),window.desktop.getBroadcastStatus()]);const passed=ok&&voice.emergencyStopped&&voice.queueLength===0&&audio.emergencyStopped&&runtime.emergencyStopped&&avatar.emergencyStopped&&music.stillPlaying()===false;setValidation(await window.desktop.recordPhase11Software({category:'emergency',passed}));setRuntimeSnapshot(runtime);setBroadcastSnapshot(broadcast);setVoiceStatus(voice);setAudioStatus(audio);setAvatarState(avatar);setNotice(passed?'Software emergency stop passed. Confirm physical output stopped, then reset explicitly.':'Emergency stop software state did not fully verify.')}catch{setNotice('Emergency stop validation failed; status remains unverified')}finally{setAudioDiagnosticBusy(false)}}
